\title{\textbf{Magnetic fields and motors}}
\date{}

\begin{document}
\maketitle
\tableofcontents
\vspace{0.5em}
\exreset

%======================================================================
\section{Magnetic field due to permanent magnets}

\subsection{Poles}
\begin{itemize}
  \item Every magnet has two poles: \textbf{N-pole} and \textbf{S-pole}.
  \item Like poles \textbf{repel}; unlike poles \textbf{attract}.
  \item Breaking a magnet always gives two smaller magnets --- never a single pole.
\end{itemize}

\begin{center}
\begin{tikzpicture}[scale=0.95]
  \draw[thick,fill=red!25] (0,0) rectangle (1.5,0.65);
  \draw[thick,fill=blue!20] (1.5,0) rectangle (3.0,0.65);
  \node[font=\small] at (0.75,0.325) {N}; \node[font=\small] at (2.25,0.325) {S};
  \draw[thick,fill=red!25] (4.0,0) rectangle (5.5,0.65);
  \draw[thick,fill=blue!20] (5.5,0) rectangle (7.0,0.65);
  \node[font=\small] at (4.75,0.325) {N}; \node[font=\small] at (6.25,0.325) {S};
  \draw[-{Latex},thick,posC] (3.05,0.45) -- (3.95,0.45);
  \draw[-{Latex},thick,posC] (3.95,0.2) -- (3.05,0.2);
  \node[font=\scriptsize,posC] at (3.5,0.95) {repel};
  \begin{scope}[yshift=-1.35cm]
    \draw[thick,fill=red!25] (0,0) rectangle (1.5,0.65);
    \draw[thick,fill=blue!20] (1.5,0) rectangle (3.0,0.65);
    \node[font=\small] at (0.75,0.325) {N}; \node[font=\small] at (2.25,0.325) {S};
    \draw[thick,fill=blue!20] (4.0,0) rectangle (5.5,0.65);
    \draw[thick,fill=red!25] (5.5,0) rectangle (7.0,0.65);
    \node[font=\small] at (4.75,0.325) {S}; \node[font=\small] at (6.25,0.325) {N};
    \draw[-{Latex},thick,negC] (3.15,0.325) -- (3.85,0.325);
    \draw[-{Latex},thick,negC] (3.85,0.325) -- (3.15,0.325);
    \node[font=\scriptsize,negC] at (3.5,-0.35) {attract};
  \end{scope}
\end{tikzpicture}
\end{center}

\subsection{Magnetic field and field lines}
A magnet (or a current) produces a \textbf{magnetic field} $\vec B$ in the space around it.
\begin{itemize}
  \item SI unit of $B$: \textbf{tesla} (T). $1\,\mathrm{T}=1\,\mathrm{N\,A^{-1}\,m^{-1}}$.
  \item Direction of $\vec B$: the direction a tiny compass N-pole would point.
\end{itemize}

\noindent Field-line rules:
\begin{enumerate}
  \item Outside a magnet, lines run from N to S.
  \item Lines never cross.
  \item Closer spacing $\Leftrightarrow$ stronger field.
\end{enumerate}

\begin{center}
\begin{tikzpicture}[scale=0.9]
  \draw[thick,fill=red!20] (-1.1,-0.32) rectangle (0,0.32);
  \draw[thick,fill=blue!15] (0,-0.32) rectangle (1.1,0.32);
  \node[font=\small] at (-0.55,0) {N}; \node[font=\small] at (0.55,0) {S};
  \foreach \y in {-0.2,0,0.2} {
    \draw[-{Latex},negC] (-2.0,\y) -- (-1.1,\y);
    \draw[-{Latex},negC] (1.1,\y) -- (2.0,\y);
  }
  \draw[-{Latex},negC] (-0.9,0.5) .. controls (-1.5,1.2) and (1.5,1.2) .. (0.9,0.5);
  \draw[-{Latex},negC] (-0.9,-0.5) .. controls (-1.5,-1.2) and (1.5,-1.2) .. (0.9,-0.5);
  \node[font=\scriptsize] at (0,-1.55) {outside: N $\to$ S};
\end{tikzpicture}
\end{center}

\noindent Into / out of the page:
\quad $\otimes$ into the page \quad\quad $\odot$ out of the page.

\note{Earth's field: a compass N-pole points roughly geographic north, so the
Earth's magnetic pole near geographic north is a \textbf{magnetic south} pole
(field lines enter there).}

%======================================================================
\section{Magnetic field due to currents}

A current produces a magnetic field. Direction by the \textbf{right-hand grip rule}:
thumb $=$ conventional current $I$; curled fingers $=$ sense of $\vec B$.

\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
Conductor & $B$ (magnitude) & Pattern \\
\midrule
Long straight wire & $B=\dfrac{\mu_0 I}{2\pi r}$ & concentric circles \\
Circular coil (centre) & $B=\dfrac{\mu_0 N I}{2r}$ & through the face of the coil \\
Long solenoid & $B=\mu_0 n I=\dfrac{\mu_0 N I}{\ell}$ & uniform inside; $\approx 0$ outside \\
\bottomrule
\end{tabular}
\end{center}
$\mu_0=4\pi\times 10^{-7}\,\mathrm{T\,m\,A^{-1}}$;\quad
$n=N/\ell$ = turns per unit length;\quad
$r$ = perpendicular distance (wire) or coil radius.

\begin{center}
\begin{tikzpicture}[scale=1.0]
  \draw[line width=1.8pt,-{Latex}] (0,-1.5) -- (0,1.7) node[above,font=\small] {$I$};
  \foreach \r in {0.5,0.85,1.2} {
    \draw[-{Latex},negC,thick] ({\r},0) arc (0:300:\r);
  }
  \node[font=\scriptsize,negC] at (1.85,0.15) {$B$};
  \node[font=\scriptsize] at (0,-1.9) {straight wire};
  \begin{scope}[xshift=4.8cm]
    \foreach \x in {0,0.32,...,3.5} {
      \draw[thick] (\x,-0.55) arc (180:360:0.16 and 0.55);
      \draw[thick,dashed] (\x,0.55) arc (0:180:0.16 and 0.55);
    }
    \draw[-{Latex},very thick,negC] (-0.25,0) -- (4.0,0);
    \node[font=\scriptsize,negC] at (4.3,0) {$B$};
    \node[font=\scriptsize] at (1.75,-1.05) {solenoid (N on right)};
  \end{scope}
\end{tikzpicture}
\end{center}

\noindent\textbf{RH grip for a solenoid:} curl fingers with the current around the coil;
thumb points to the N-pole end (field inside along the axis).

\ex
A straight wire $X$ carries $5\,\mathrm{A}$. Point $P$ is $8\,\mathrm{cm}$ from the wire.
\begin{enumerate}
  \item Find $B$ at $P$.
  \item Another wire $Y$ carrying $2\,\mathrm{A}$ is placed so that $P$ is mid-way between $X$ and $Y$.
        Find the resultant $B$ at $P$ if the currents are
        \begin{enumerate}
          \item in opposite directions;
          \item in the same direction.
        \end{enumerate}
\end{enumerate}
($\mu_0=4\pi\times 10^{-7}\,\mathrm{T\,m\,A^{-1}}$)

\sol
\begin{enumerate}
  \item $B_X=\dfrac{\mu_0 I}{2\pi r}
        =\dfrac{(4\pi\times 10^{-7})(5)}{2\pi(0.08)}=1.25\times 10^{-5}\,\mathrm{T}$.
  \item $B_Y=\dfrac{(4\pi\times 10^{-7})(2)}{2\pi(0.08)}=5\times 10^{-6}\,\mathrm{T}$.
        \begin{enumerate}
          \item Opposite currents $\Rightarrow$ fields at $P$ in the \emph{same} sense:
                $B=B_X+B_Y=1.75\times 10^{-5}\,\mathrm{T}$.
          \item Same currents $\Rightarrow$ fields opposite:
                $B=B_X-B_Y=7.5\times 10^{-6}\,\mathrm{T}$.
        \end{enumerate}
\end{enumerate}

\ex
A solenoid of length $30\,\mathrm{cm}$ has $180$ turns and carries $5\,\mathrm{A}$.
\begin{enumerate}
  \item Identify the poles at ends $A$ and $B$ (current sense: from $A$ end, anticlockwise when viewed from $A$).
  \item Find $B$ at the centre.
  \item If $I$ is halved, what happens to (b)?
  \item Give three ways to increase $B$.
\end{enumerate}

\sol
\begin{enumerate}
  \item Viewed from $A$, anticlockwise current $\Rightarrow$ $A$ is S, $B$ is N (RH grip).
  \item $B=\dfrac{\mu_0 N I}{\ell}
        =\dfrac{(4\pi\times 10^{-7})(180)(5)}{0.30}=3.77\times 10^{-3}\,\mathrm{T}$.
  \item $B$ is halved ($B\propto I$).
  \item Increase $I$; increase $N$ (same $\ell$); insert a soft-iron core.
\end{enumerate}

\worked{2021}{25}{C}{63}{../2021_q25.png}{%
Wire at $P$: $0.3\,\mathrm{A}$ into the paper.
At $R$, $B_P=\mu_0(0.3)/(2\pi\cdot 0.15)$.
To cancel, wire at $Q$ must produce equal $B$ at $R$ in the opposite direction
$\Rightarrow$ current \textbf{out of} the paper.
$QR=0.05\,\mathrm{m}=PQ/3$ wait: $PQ=10\,\mathrm{cm}$, $QR=5\,\mathrm{cm}$, so
$I_Q=0.3\times(0.05/0.15)=0.1\,\mathrm{A}$ $\Rightarrow$ \textbf{C}.}

\worked{2018}{27}{C}{62}{../2018_q27.png}{%
Magnet field between poles: N $\to$ S (leftward).
Current out of paper $\Rightarrow$ anticlockwise $B$ around the wire.
Only at \textbf{R} (below the wire) can the wire's field oppose the magnet's field
and cancel $\Rightarrow$ \textbf{C}.}

%======================================================================
\section{Electromagnets}

An \textbf{electromagnet} is a current-carrying coil, usually with a soft-iron core.

\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
 & Soft iron & Steel \\
\midrule
Easy to magnetise? & Yes & Harder \\
Keeps magnetism when $I=0$? & No (temporary) & Yes (permanent) \\
Use & Electromagnets, cores & Permanent magnets \\
\bottomrule
\end{tabular}
\end{center}

Ways to strengthen: larger $I$, more turns, soft-iron core, smaller air gap.
Using a.c.\ instead of d.c.\ does \emph{not} help for a steady electromagnet.

\note{Stretching a solenoid at fixed $N$ and $I$ halves $n$ if length doubles,
so $B=\mu_0 n I$ halves.}

%======================================================================
\section{Force on a current-carrying conductor}

\subsection{Magnitude}
\[
F = B I L \sin\theta,
\]
where $\theta$ is the angle between the current and $\vec B$.
\begin{itemize}
  \item $\theta=90^\circ$ (wire $\perp$ field): $F=BIL$ (maximum).
  \item $\theta=0^\circ$ (wire $\parallel$ field): $F=0$.
\end{itemize}

\subsection{Fleming's left-hand rule (motor rule)}
Hold the left hand with thumb, first finger and second finger mutually perpendicular:
\begin{itemize}
  \item thu\textbf{M}b --- Motion / Force $F$
  \item \textbf{F}irst finger --- Field $B$
  \item se\textbf{C}ond finger --- Current $I$
\end{itemize}

\begin{center}
\begin{tikzpicture}[scale=0.95]
  \draw[thick,fill=orange!15] (0,0) -- (1.7,0.15) -- (1.8,1.5) -- (0.15,1.35) -- cycle;
  \draw[thick,fill=orange!20] (0.25,1.4) -- (0.05,2.4) -- (0.5,2.45) -- (0.65,1.45);
  \draw[thick,fill=orange!20] (0.7,1.45) -- (0.9,2.25) -- (1.3,2.2) -- (1.1,1.4);
  \draw[thick,fill=orange!20] (-0.05,0.85) -- (-1.05,1.25) -- (-0.9,1.6) -- (0.12,1.2);
  \draw[-{Latex},very thick,posC] (-0.15,1.25) -- (-1.5,1.75) node[left,font=\small] {$F$};
  \draw[-{Latex},very thick,negC] (0.35,2.4) -- (0.35,3.15) node[above,font=\small] {$B$};
  \draw[-{Latex},very thick,blue!50!black] (1.1,2.2) -- (2.15,2.55) node[right,font=\small] {$I$};
\end{tikzpicture}
\end{center}

\subsection{Catapult field}
The wire's own circular field reinforces the external field on one side and weakens it on the other.
The wire is pushed from the \textbf{denser} side toward the weaker side.

\worked{2013}{26}{C}{42}{../2013_q26.png}{%
Current into paper $\Rightarrow$ clockwise $B$ (RH grip).
Lines denser on the left $\Rightarrow$ external $\vec B$ upward (S at $X$, N at $Y$).
Force dense $\to$ sparse: to the \textbf{right}.
Fleming: $B$ up, $I$ into page $\Rightarrow$ $F$ right $\Rightarrow$ \textbf{C}.}

\worked{2013}{28}{C}{42}{../2013_q28.png}{%
Current through the rod $Y\to X$. From $Y$: $I$ into the paper; $\vec B$ vertically down.
Fleming: $B$ down, $I$ into page $\Rightarrow$ $F_B$ horizontally to the \textbf{left}
(diagram~C) $\Rightarrow$ \textbf{C}.}

%======================================================================
\section{Force between parallel wires}

Each wire sits in the other's field, so each feels $F=BIL$.
\begin{itemize}
  \item Currents in the \textbf{same} direction: wires \textbf{attract}.
  \item Currents in \textbf{opposite} directions: wires \textbf{repel}.
\end{itemize}
The two forces are an action--reaction pair (equal magnitude, opposite direction).

\begin{center}
\begin{tikzpicture}[scale=0.95]
  \draw[line width=1.5pt,-{Latex}] (0,-1.1) -- (0,1.3) node[above,font=\small] {$I$};
  \draw[line width=1.5pt,-{Latex}] (2.0,-1.1) -- (2.0,1.3) node[above,font=\small] {$I$};
  \draw[-{Latex},thick,negC] (0.2,0.15) -- (1.8,0.15);
  \draw[-{Latex},thick,negC] (1.8,-0.15) -- (0.2,-0.15);
  \node[font=\scriptsize] at (1.0,-1.45) {same $I$: attract};
  \begin{scope}[xshift=4.6cm]
    \draw[line width=1.5pt,-{Latex}] (0,-1.1) -- (0,1.3) node[above,font=\small] {$I$};
    \draw[line width=1.5pt,-{Latex}] (2.0,1.3) -- (2.0,-1.1) node[below,font=\small] {$I$};
    \draw[-{Latex},thick,posC] (0.2,0) -- (-0.55,0);
    \draw[-{Latex},thick,posC] (1.8,0) -- (2.55,0);
    \node[font=\scriptsize] at (1.0,-1.45) {opposite $I$: repel};
  \end{scope}
\end{tikzpicture}
\end{center}

\ex
Parallel wires $X$ and $Y$ are $20\,\mathrm{cm}$ apart. $I_X=3\,\mathrm{A}$, $I_Y=6\,\mathrm{A}$
(opposite directions).
\begin{enumerate}
  \item Find $B$ due to $Y$ at the position of $X$.
  \item Find the magnetic force per unit length on $X$.
  \item Mary says: ``Since $I_Y=2I_X$, the force on $Y$ is twice that on $X$.'' Comment.
\end{enumerate}

\sol
\begin{enumerate}
  \item $B_Y=\dfrac{\mu_0 I_Y}{2\pi r}
        =\dfrac{(4\pi\times 10^{-7})(6)}{2\pi(0.20)}=6\times 10^{-6}\,\mathrm{T}$.
  \item $\dfrac{F}{L}=B_Y I_X=(6\times 10^{-6})(3)=1.8\times 10^{-5}\,\mathrm{N\,m^{-1}}$.
  \item Incorrect. By Newton's third law the forces are equal in magnitude
        (action--reaction).
\end{enumerate}

\worked{2013}{27}{C}{59}{../2013_q27.png}{%
Equal currents; $O$ equidistant.
Three wires give $\vec B$ into the paper at $O$; wire $R$ gives $\vec B$ out.
Removing $R$ removes the opposing field and \textbf{increases} $|\vec B|$ at $O$
$\Rightarrow$ \textbf{C}.}

\worked{2014}{26}{A}{58}{../2014_q26.png}{%
Equal distances. Fields of $P$ and $R$ (both into paper) cancel at $O$.
Fields of $Q$ (into) and $S$ (out) both point along $OP$.
Resultant along $\overrightarrow{OP}$ $\Rightarrow$ \textbf{A}.}

\worked{2024}{26}{B}{49}{../2024_q26.png}{%
$I_1$ up the vertical wire $\Rightarrow$ at $MN$ (to the right), RH grip gives
$\vec B$ into the paper. $I_2$ toward $M$ (left).
Fleming: $B$ into page, $I$ left $\Rightarrow$ force on $MN$ \textbf{downward}
$\Rightarrow$ \textbf{B}.}

%======================================================================
\section{Force on a moving charge}

A charge $q$ moving at velocity $\vec v$ in a magnetic field experiences
\[
F = |q|\,v B\sin\theta
\qquad(\vec F = q\,\vec v\times\vec B).
\]
\begin{itemize}
  \item $q>0$: Fleming left hand with ``current'' along $\vec v$.
  \item $q<0$ (electron): force is \textbf{opposite} to the positive-charge prediction.
  \item $\vec F\perp\vec v$ always $\Rightarrow$ speed unchanged; magnetic force does no work.
\end{itemize}

\subsection{Circular path}
If $\vec v\perp\vec B$ and $B$ is uniform, $F=qvB$ provides the centripetal force:
\[
qvB = \frac{mv^{2}}{r}
\quad\Rightarrow\quad
r = \frac{mv}{qB},\qquad
T = \frac{2\pi m}{qB}.
\]

\ex
An electron moves in a circle in $B=0.01\,\mathrm{T}$ at $v=6\times 10^{7}\,\mathrm{m\,s^{-1}}$.
($e=1.6\times 10^{-19}\,\mathrm{C}$, $m=9.1\times 10^{-31}\,\mathrm{kg}$.)
\begin{enumerate}
  \item Find the radius.
  \item Find the period.
\end{enumerate}

\sol
\begin{enumerate}
  \item $r=\dfrac{mv}{eB}
        =\dfrac{(9.1\times 10^{-31})(6\times 10^{7})}{(0.01)(1.6\times 10^{-19})}
        =0.034\,\mathrm{m}$.
  \item $T=\dfrac{2\pi r}{v}=\dfrac{2\pi(0.034)}{6\times 10^{7}}=3.6\times 10^{-9}\,\mathrm{s}$
        (or $T=2\pi m/(eB)$).
\end{enumerate}

\qbtext{Electron entering a magnetic field}{%
An electron moving towards the right enters a uniform magnetic field pointing out of the page.
Direction of the magnetic force as it enters?
\begin{itemize}[nosep]
  \item[A.] Towards the left
  \item[B.] Towards the right
  \item[C.] Downwards
  \item[D.] Upwards
\end{itemize}}{C}{%
Positive charge right + $B$ out $\Rightarrow$ Fleming gives force \textbf{up}.
Electron: reverse $\Rightarrow$ \textbf{downwards} $\Rightarrow$ \textbf{C}.}

\note{Hall effect (brief): charges in a current-carrying strip in a perpendicular $B$
are deflected to one face, producing a small transverse Hall voltage
$V_H=BI/(nqt)$. Useful for sensing $B$; not a DSE calculation focus.}

%======================================================================
\section{d.c.\ motor}

\subsection{Structure}
\begin{enumerate}
  \item permanent magnets (or electromagnets)
  \item coil on an axle
  \item carbon brushes
  \item split-ring \textbf{commutator}
\end{enumerate}

Sides of the coil perpendicular to $\vec B$ feel equal and opposite forces
$\Rightarrow$ a couple (torque) that rotates the coil.

\begin{center}
\begin{tikzpicture}[scale=0.92]
  \draw[thick,fill=red!20] (-0.15,0) rectangle (0.7,2.2);
  \node[font=\small] at (0.275,1.1) {N};
  \draw[thick,fill=blue!15] (3.7,0) rectangle (4.55,2.2);
  \node[font=\small] at (4.125,1.1) {S};
  \draw[-{Latex},negC] (0.8,1.75) -- (3.6,1.75);
  \draw[-{Latex},negC] (0.8,0.45) -- (3.6,0.45);
  \draw[thick,fill=gray!10] (1.2,0.65) rectangle (3.2,1.55);
  \draw[-{Latex},very thick,posC] (1.2,1.1) -- (1.2,0.1) node[below,font=\scriptsize] {$F$};
  \draw[-{Latex},very thick,posC] (3.2,1.1) -- (3.2,2.1) node[above,font=\scriptsize] {$F$};
  \begin{scope}[xshift=5.9cm,yshift=0.35cm]
    \draw[thick] (0,0.7) circle (0.5);
    \draw[thick,fill=yellow!30] (-0.07,0.2) rectangle (0.07,1.2);
    \draw[thick,fill=gray!40] (-0.5,0.85) rectangle (-0.32,1.2);
    \draw[thick,fill=gray!40] (0.32,0.85) rectangle (0.5,1.2);
    \node[font=\scriptsize] at (0,-0.2) {commutator};
    \node[font=\scriptsize] at (0,-0.5) {+ brushes};
  \end{scope}
\end{tikzpicture}
\end{center}

\subsection{Role of the commutator}
The commutator reverses the current in the coil every half-turn so the torque
keeps the same sense and the coil continues to rotate one way.
At the instant the coil plane is perpendicular to $\vec B$, torque is briefly zero;
\textbf{inertia} carries the coil past that position.

Ways to increase turning speed: larger $I$, stronger $B$, more turns, larger coil area
(within the field).

\note{Commutator reverses current in the \emph{coil}, not battery polarity.
Curved pole pieces give a more radial field $\Rightarrow$ more nearly constant torque.}

\worked{2015}{24}{B}{44}{../2015_q24.png}{%
At the instant shown, flux change rate is greatest $\Rightarrow$ max induced e.m.f.\ (A true).
Lenz: magnetic forces oppose the rotation (D true).
Force on side $P$ (moving out) is into the paper (C true).
Current sense in B is the wrong way $\Rightarrow$ \textbf{B} is incorrect.}

\worked{2017}{28}{C}{46}{../2017_q28.png}{%
Motional e.m.f.\ $\mathcal{E}=Bdv$; $I=Bdv/R$.
Free positive charges in the moving rod feel $\vec F=q\vec v\times\vec B$ toward $X$,
so current through $R$ is $X\to Y$ $\Rightarrow$ \textbf{C}.}

%======================================================================
\section{Summary}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Idea & Formula / rule \\
\midrule
Straight wire & $B=\mu_0 I/(2\pi r)$ (RH grip) \\
Solenoid & $B=\mu_0 n I$ \\
Force on wire & $F=BIL\sin\theta$ (Fleming left) \\
Force on charge & $F=|q|vB\sin\theta$;\quad $r=mv/(qB)$ \\
Parallel wires & same $I$ attract; opposite $I$ repel \\
$\mu_0$ & $4\pi\times 10^{-7}\,\mathrm{T\,m\,A^{-1}}$ \\
Motor & commutator reverses coil current each half-turn \\
\bottomrule
\end{tabular}
\end{center}

\note{Checklist: (1)~RH grip for $B$, or Fleming left for force?
(2)~Positive or negative charge?
(3)~Are $\vec I$ (or $\vec v$) and $\vec B$ perpendicular?
(4)~Dense lines $\Rightarrow$ force toward sparse side.
(5)~What does the commutator reverse?}

