\ex
A rod of length $\ell=0.20\,\mathrm{m}$ moves at $v=4.0\,\mathrm{m\,s^{-1}}$ on rails
in $B=0.50\,\mathrm{T}$ (into the page). Rail separation $=\ell$; $R=2.0\,\Omega$.
\begin{enumerate}
  \item Find the induced e.m.f.
  \item Find the induced current.
  \item Which end of the rod is at higher potential? (rod moving to the right)
\end{enumerate}

\sol
\begin{enumerate}
  \item $\mathcal{E}=B\ell v=(0.50)(0.20)(4.0)=0.40\,\mathrm{V}$.
  \item $I=\mathcal{E}/R=0.40/2.0=0.20\,\mathrm{A}$.
  \item Positive charges feel $\vec F=q\vec v\times\vec B$ toward the top end
        (Fleming / $\vec v\times\vec B$) $\Rightarrow$ top end higher potential.
\end{enumerate}

